    '# ---------------------------------------------------------------------- parallel moves\n'
    '# Consecutive moves share a step if their line spans stay apart along x and y while moving, and no\n'
    "# crossing of one move's rows with the other's columns passes over an atom not moved in the step.\n"
    '\n'
    '\n'
    '@dataclass(frozen=True)\n'
    'class AodLines:\n'
    '    """The lines a move uses, each mapped to its target line."""\n'
    '\n'
    '    rows: dict[int, int]\n'
    '    cols: dict[int, int]\n'
    '\n'
    '    @classmethod\n'
    '    def of(cls, mapping: dict[Site, Site]) -> AodLines:\n'
    '        return cls({y: y2 for (_, y), (_, y2) in mapping.items()}, {x: x2 for (x, _), (x2, _) in mapping.items()})\n'
    '\n'
    '\n'
    'def _apart(a: dict[int, int], b: dict[int, int]) -> bool:\n'
    '    (a_lo, a_hi), (b_lo, b_hi) = (min(a), max(a)), (min(b), max(b))\n'
    '    return (a_hi < b_lo and a[a_hi] < b[b_lo]) or (b_hi < a_lo and b[b_hi] < a[a_lo])\n'
    '\n'
    '\n'
    'def _path(start: Site, end: Site) -> list[Site]:\n'
    '    """The grid sites a point passes moving in a straight line from `start` to `end`."""\n'
    '    dx, dy = end[0] - start[0], end[1] - start[1]\n'
    '    steps = math.gcd(dx, dy)\n'
    '    if steps == 0:\n'
    '        return [start]\n'
    '    return [(start[0] + i * dx // steps, start[1] + i * dy // steps) for i in range(steps + 1)]\n'
    '\n'
    '\n'
    'def can_run_in_parallel(a: AodLines, b: AodLines, stationary: set[Site]) -> bool:\n'
