    'def euler_zxz(u: np.ndarray) -> tuple[list[tuple[str, float]], float]:\n'
    '    """Decompose a 2x2 unitary into circuit-order [rz(d), rx(p), rz(l)] plus a global phase.\n'
    '\n'
